describe('Dynamic Content Accessibility Announcements', () => {
  beforeEach(() => {
    cy.visit('/dynamic-content');
  });

  it('should announce dynamic content updates for screen readers', () => {
    // Intercept the API call to fetch dynamic content
    cy.intercept('GET', '/api/dynamic-content').as('getDynamicContent');

    // Verify initial state
    cy.get('[data-testid="content-container"]').should('be.visible');
    cy.get('[data-testid="content-container"]').should('contain', 'Initial content');

    // Trigger the API call
    cy.wait('@getDynamicContent');

    // Verify screen reader announcement
    cy.get('[data-testid="screen-reader-announcer"]').should('be.visible');
    cy.get('[data-testid="screen-reader-announcer"]').should('contain', 'Dynamic content updated');

    // Verify content has been updated
    cy.get('[data-testid="content-container"]').should('contain', 'Updated content');

    // Verify announcement is clear and descriptive
    cy.get('[data-testid="screen-reader-announcer"]').should('have.css', 'opacity', '1');
    cy.get('[data-testid="screen-reader-announcer"]').should('contain', 'Content has been refreshed');
  });

  it('should handle multiple dynamic content updates without repetitive announcements', () => {
    // Intercept the API call to fetch dynamic content
    cy.intercept('GET', '/api/dynamic-content').as('getDynamicContent');

    // Trigger the first API call
    cy.wait('@getDynamicContent');
    cy.get('[data-testid="screen-reader-announcer"]').should('contain', 'Dynamic content updated');

    // Trigger the second API call
    cy.wait('@getDynamicContent');

    // Verify screen reader announces only once
    cy.get('[data-testid="screen-reader-announcer"]').should('contain', 'Dynamic content updated');

    // Verify content has been updated twice
    cy.get('[data-testid="content-container"]').should('contain', 'Updated content');
    cy.get('[data-testid="content-container"]').should('contain', 'Second update');

    // Verify announcement is clear and descriptive
    cy.get('[data-testid="screen-reader-announcer"]').should('have.css', 'opacity', '1');
    cy.get('[data-testid="screen-reader-announcer"]').should('contain', 'Content has been refreshed twice');
  });
});
